CREATE OR REPLACE FUNCTION public.client_workspace(_client uuid)
 RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$ DECLARE scope jsonb:=public.client_workspace_scope(_client); c public.clients; contacts jsonb; sites jsonb; sheets jsonb; BEGIN
 SELECT * INTO c FROM public.clients WHERE id=_client;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'address',s.address,'store_code',s.store_code) ORDER BY s.name),'[]'::jsonb) INTO sites FROM public.sites s WHERE s.client_id=c.id AND s.company_id=c.company_id AND ((scope->>'all_sites')::boolean OR to_jsonb(s.id::text)<@coalesce(scope->'site_ids','[]'::jsonb));
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'first_name',x.first_name,'last_name',x.last_name,'email',x.email,'phone',x.phone,'role_title',x.role_title,'has_whatsapp',x.has_whatsapp,'receives_job_sheets',x.receives_job_sheets,'site_id',x.site_id,'site_ids',x.site_ids,'all_sites',x.all_sites,'delivery_preferences',x.delivery_preferences) ORDER BY x.first_name),'[]'::jsonb) INTO contacts FROM public.client_contacts x WHERE x.client_id=c.id AND x.company_id=c.company_id AND ((scope->>'office')::boolean OR (x.id::text=scope->>'contact') OR ((scope->>'admin')::boolean AND ((scope->>'all_sites')::boolean OR (NOT x.all_sites AND to_jsonb(x.site_ids)<@scope->'site_ids'))));
 SELECT coalesce(jsonb_agg(q),'[]'::jsonb) INTO sheets FROM (SELECT s.id,s.jobsheet_number,s.created_at,s.site_id,s.reported_fault,s.repairs_performed FROM public.job_sheets s WHERE s.client_id=c.id AND s.company_id=c.company_id AND s.status='completed' AND ((scope->>'office')::boolean OR (scope->>'all_sites')::boolean OR (s.site_id IS NOT NULL AND to_jsonb(s.site_id::text)<@scope->'site_ids')) ORDER BY s.created_at DESC LIMIT 100) q;
 RETURN jsonb_build_object('id',c.id,'name',c.name,'company_id',c.company_id,'scope',scope,'sites',sites,'contacts',contacts,'sheets',sheets,'module_on',public.company_module_access(c.company_id,'client_portal'));
END $function$;